package pca

// Differential kill test for intent_acc.go (rule 15: accumulator / monitor declarations, selection and values, pre-states,
// reservation receipts, sequencer key sets, receipt verification against the sequenced holder) against the TypeScript
// reference packages/pca/src/intent-acc.ts: testdata/k042-intentacc.json is generated by
// tools/pca-audit/java-mutate/k042-intentacc-oracle.mjs (shared with the Java suite). Go reports verdicts, not reason
// texts, for the *Error functions: the verdict (refused or not) is compared exactly.

import (
	"fmt"
	"os"
	"strings"
	"testing"
)

type k042AccCase struct {
	Name string `json:"name"`
	Fn   string `json:"fn"`
	Args []any  `json:"args"`
	Out  any    `json:"out"`
}

var k042AccCases []k042AccCase

func k042AccLoad(t *testing.T) []k042AccCase {
	if k042AccCases == nil {
		add := func(path string, key string, minimum int) {
			b, err := os.ReadFile(path)
			if err != nil {
				t.Fatal(err)
			}
			// parse leniently (the lexemes matter), then re-shape
			doc, err := ParseJSONLenient(b)
			if err != nil {
				t.Fatal(err)
			}
			list, ok := doc.([]any)
			if key != "" {
				list, _ = doc.(map[string]any)[key].([]any)
			} else if !ok {
				t.Fatalf("%s: not a list", path)
			}
			if len(list) < minimum {
				t.Fatalf("%s: corpus too small: %d", path, len(list))
			}
			for _, o := range list {
				m := o.(map[string]any)
				k042AccCases = append(k042AccCases, k042AccCase{Name: m["name"].(string), Fn: m["fn"].(string), Args: m["args"].([]any), Out: m["out"]})
			}
		}
		add("testdata/k042-intentacc.json", "", 1500)
		// the conformance corpus file (intent-state-vectors.json): the same accumulator / receipt cases plus the session-history cases
		add(dir+"intent-state-vectors.json", "cases", 3000)
	}
	return k042AccCases
}

func k042AccRun(t *testing.T, fn string, f func(a []any) any) { t.Helper(); k042AccRunN(t, fn, nil, f) }

// k042AccRunN is k042AccRun with a normalizer over the reference's expected output (e.g. dropping reason texts Go does not carry).
func k042AccRunN(t *testing.T, fn string, norm func(any) any, f func(a []any) any) {
	t.Helper()
	var bad []string
	n := 0
	for _, c := range k042AccLoad(t) {
		if c.Fn != fn {
			continue
		}
		n++
		var got any
		func() {
			defer func() {
				if r := recover(); r != nil {
					got = fmt.Sprintf("THREW %v", r)
				}
			}()
			got = f(normalizeJSON(c.Args).([]any))
		}()
		out := normalizeJSON(c.Out)
		if norm != nil {
			out = norm(out)
		}
		want, _ := canonicalLenient(out)
		g, ok := canonicalLenient(normalizeJSON(got))
		if !ok {
			g = fmt.Sprintf("%v", got)
		}
		if want != g {
			bad = append(bad, fmt.Sprintf("%s\n    want %s\n    got  %s", c.Name, want, g))
		}
	}
	if n == 0 {
		t.Fatalf("no cases for %s", fn)
	}
	if len(bad) > 0 {
		if len(bad) > 30 {
			bad = bad[:30]
		}
		t.Fatalf("%s: %d/%d cases differ from the reference:\n  %s", fn, len(bad), n, strings.Join(bad, "\n  "))
	}
}

// k042AccVerdictRun compares only whether a reference reason is null or not.
func k042AccVerdictRun(t *testing.T, fn string, f func(a []any) bool) {
	t.Helper()
	var bad []string
	n := 0
	for _, c := range k042AccLoad(t) {
		if c.Fn != fn {
			continue
		}
		n++
		wantOK := c.Out == nil
		var gotOK bool
		var thrown any
		func() {
			defer func() { thrown = recover() }()
			gotOK = f(normalizeJSON(c.Args).([]any))
		}()
		if thrown != nil || gotOK != wantOK {
			bad = append(bad, fmt.Sprintf("%s: want ok=%v got ok=%v (threw %v) ref reason %v", c.Name, wantOK, gotOK, thrown, c.Out))
		}
	}
	if n == 0 {
		t.Fatalf("no cases for %s", fn)
	}
	if len(bad) > 0 {
		if len(bad) > 30 {
			bad = bad[:30]
		}
		t.Fatalf("%s: %d/%d verdicts differ:\n  %s", fn, len(bad), n, strings.Join(bad, "\n  "))
	}
}

func k042M(v any) map[string]any {
	m, _ := v.(map[string]any)
	return m
}

func TestK042AccDeclErrors(t *testing.T) {
	k042AccVerdictRun(t, "accumulatorDeclError", func(a []any) bool { return accumulatorDeclError(a[0]) == "" })
	k042AccVerdictRun(t, "monitorDeclError", func(a []any) bool { return monitorDeclError(a[0]) == "" })
	k042AccVerdictRun(t, "trackedKeySetError", func(a []any) bool { return trackedKeySetError(a[0]) == "" })
	k042AccRun(t, "monitorStates", func(a []any) any {
		out := []any{}
		for _, s := range monitorStates(k042M(a[0])) {
			out = append(out, s)
		}
		return out
	})
}

func TestK042AccTrackedKeySetTexts(t *testing.T) {
	// Go spells the tracked key-set reasons exactly like the reference: compare the text too
	k042AccRun(t, "trackedKeySetError", func(a []any) any {
		if s := trackedKeySetError(a[0]); s != "" {
			return s
		}
		return nil
	})
}

func TestK042AccPreState(t *testing.T) {
	k042AccVerdictRun(t, "preStateError", func(a []any) bool { return preStateOK(a[0].(string), a[1]) })
	k042AccRun(t, "preValue", func(a []any) any { return jsNumber(preValue(a[0].(string), k042M(a[1]))) })
	k042AccRun(t, "combineAcc", func(a []any) any {
		v := k042M(a[2])
		k, _ := v["key"].(string)
		f, _ := jsNum(v["val"])
		post, ok := combineAcc(a[0].(string), k042M(a[1]), accValue{val: f, key: k})
		if !ok {
			return nil
		}
		return jsNumber(post)
	})
}

func TestK042AccSelectionAndValues(t *testing.T) {
	k042AccRun(t, "accSelects", func(a []any) any {
		ok, throws := accSelects(k042M(a[0]), a[1].(string), a[2], a[2] != nil)
		if throws {
			return "THREW"
		}
		return ok
	})
	dropReason := func(o any) any {
		if m, ok := o.(map[string]any); ok && m["ok"] == false {
			return map[string]any{"ok": false}
		}
		return o
	}
	k042AccRunN(t, "accValueOf", dropReason, func(a []any) any {
		v, ok, throws := accValueOf(k042M(a[0]), a[1].(string), k042M(a[2]), a[3], a[3] != nil)
		if throws {
			return "THREW"
		}
		if !ok {
			return map[string]any{"ok": false}
		}
		var key any
		if v.key != "" {
			key = v.key
		}
		return map[string]any{"ok": true, "val": jsNumber(v.val), "key": key}
	})
}

func TestK042AccReceipts(t *testing.T) {
	k042AccRun(t, "receiptArithmeticOk", func(a []any) any {
		f, _ := jsNum(a[2])
		return receiptArithmeticOk(a[0].(string), k042M(a[1]), f)
	})
	k042AccRun(t, "pcactnReservationDigest", func(a []any) any {
		d, ok := pcactnReservationDigest(k042M(a[0]))
		if !ok {
			return nil
		}
		return d
	})
	k042AccVerdictRun(t, "receiptShapeError", func(a []any) bool { return accReceiptShapeOK(a[0]) })
	k042AccVerdictRun(t, "keySetShapeError", func(a []any) bool { return sequencerKeySetShapeOK(a[0]) })
}

func TestK042AccKeySetsAndHolder(t *testing.T) {
	k042AccRun(t, "verifyKeySet", func(a []any) any {
		_, rootPqPresent := a[2], a[3] == true
		return verifySequencerKeySet(a[0], a[1], a[2], rootPqPresent)
	})
	k042AccRun(t, "verifyReceiptSignature", func(a []any) any {
		r, ok := a[0].(map[string]any)
		if !ok {
			return false
		}
		var pins map[string]string
		if p, ok := a[2].(map[string]any); ok {
			pins = map[string]string{}
			for k, v := range p {
				pins[k], _ = v.(string)
			}
		}
		return verifyAccReceiptSignature(r, a[1].(string), pins)
	})
	k042AccRun(t, "verifyReceiptAgainstHolder", func(a []any) any {
		fl := func(v any) float64 { f, _ := jsNum(v); return f }
		keySets, _ := a[2].([]any)
		var tracked map[string]any
		if tm, ok := a[6].(map[string]any); ok {
			tracked = tm
		}
		return verifyReceiptAgainstHolder(k042M(a[0]), k042M(a[1]), keySets, fl(a[3]), receiptFreshness{maxReceiptAgeMs: fl(a[4]), maxKeySetAgeMs: fl(a[5]), tracked: tracked})
	})
}

// ---- the session-history cases (intent_history.go; conformance/intent-state-vectors.json) ----------------------------------

func TestIntentStateHistory(t *testing.T) {
	schemaOf := func(v any) (any, bool) { return v, v != nil }
	k042AccRun(t, "inWindow", func(a []any) any { return inWindow(k042M(a[0]), a[1], a[2]) })
	k042AccRun(t, "accKeyOf", func(a []any) any {
		k, ok := accKeyOf(k042M(a[0]), k042M(a[1]))
		if !ok {
			return nil
		}
		return k
	})
	k042AccRun(t, "accPreState", func(a []any) any {
		cand := k042M(a[2])
		schema, have := schemaOf(a[3])
		hist, _ := a[1].([]any)
		pre, ok := accPreState(k042M(a[0]), hist, k042M(cand["params"]), cand["t"], schema, have)
		if !ok {
			return map[string]any{"throws": true}
		}
		return pre
	})
	k042AccRun(t, "accPost", func(a []any) any {
		cand := k042M(a[2])
		schema, have := schemaOf(a[3])
		hist, _ := a[1].([]any)
		post, ok := accPost(k042M(a[0]), hist, cand["verb"].(string), k042M(cand["params"]), cand["t"], schema, have)
		if !ok {
			return map[string]any{"throws": true}
		}
		return jsNumber(post)
	})
	k042AccRun(t, "monitorStep", func(a []any) any { return monitorStep(k042M(a[0]), a[1].(string), k042M(a[2])) })
	k042AccRun(t, "monitorState", func(a []any) any {
		hist, _ := a[1].([]any)
		return monitorState(k042M(a[0]), hist)
	})
}

// TestIntentStateCorpusIsFullyRun: every function of the corpus file has a runner above (a new function without one fails).
func TestIntentStateCorpusIsFullyRun(t *testing.T) {
	known := map[string]bool{}
	for _, f := range []string{"accumulatorDeclError", "monitorDeclError", "monitorStates", "trackedKeySetError", "preStateError", "preValue", "combineAcc", "accSelects", "accValueOf", "receiptArithmeticOk", "pcactnReservationDigest", "receiptShapeError", "keySetShapeError", "verifyKeySet", "verifyReceiptSignature", "verifyReceiptAgainstHolder", "inWindow", "accKeyOf", "accPreState", "accPost", "monitorStep", "monitorState"} {
		known[f] = true
	}
	b, err := os.ReadFile(dir + "intent-state-vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	doc, err := ParseJSONLenient(b)
	if err != nil {
		t.Fatal(err)
	}
	m := doc.(map[string]any)
	if m["format"] != "pca-intent-state-vectors" || num(m["ver"]) != 1 {
		t.Fatalf("unexpected format %v / ver %v", m["format"], m["ver"])
	}
	seen := map[string]int{}
	for _, c := range m["cases"].([]any) {
		fn := c.(map[string]any)["fn"].(string)
		if !known[fn] {
			t.Errorf("no runner for corpus function %q", fn)
		}
		seen[fn]++
	}
	for f := range known {
		if seen[f] == 0 {
			t.Errorf("corpus has no case for %q", f)
		}
	}
}
